pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }
    function testFuzz_property(uint8 seed, uint256 extra) public {
        uint256 amount = 10;
        address player = address(uint160(uint256(keccak256(abi.encode(seed, extra)))));
        vm.assume(player != address(0) && player != address(c));
        vm.deal(player, amount);

        vm.warp(1);
        vm.roll(1);

        vm.prank(player);
        try c.play{value: amount}() {
            uint256 potAfter = c.pot();

            assertTrue(c.pot() == 0 || address(c).balance >= c.pot());
        } catch {
            uint256 potAfter = c.pot();
            assertTrue(potAfter == 0 || address(c).balance >= potAfter);
        }
    }

    receive() external payable {}
}
